from typing import Any, Dict
from copy import deepcopy

def deep_merge(a: Dict[Any, Any], b: Dict[Any, Any]) -> Dict[Any, Any]:
    """Recursively merge dict b into a (b wins on leaf conflicts).

    Args:
        a: Base dict; not mutated.
        b: Dict to merge on top.

    Returns:
        A new dict with nested dicts merged recursively.

    Examples:
        >>> a = {"x": {"y": 1, "z": 2}}; b = {"x": {"y": 99}, "w": 7}
        >>> deep_merge(a, b)
        {'x': {'y': 99, 'z': 2}, 'w': 7}
        >>> deep_merge({}, {})
        {}
    """
    out: Dict[Any, Any] = dict(a)
    for k, v in b.items():
        if k in out and isinstance(out[k], dict) and isinstance(v, dict):
            out[k] = deep_merge(out[k], v)
        else:
            out[k] = deepcopy(v) if isinstance(v, (dict, list)) else v
    return out

from typing import Any, Dict, Hashable, List, Tuple

def first_index_and_count(lst: List[Hashable]) -> Dict[Hashable, Tuple[int, int]]:
    """Compute (first index, total count) for each element of lst.

    Args:
        lst: A list.

    Returns:
        A dict mapping each element to (first_index, count).

    Examples:
        >>> first_index_and_count(["a", "b", "a", "c", "a", "b"])
        {'a': (0, 3), 'b': (1, 2), 'c': (3, 1)}
        >>> first_index_and_count([])
        {}
    """
    out: Dict[Hashable, Tuple[int, int]] = {}
    for i, x in enumerate(lst):
        if x in out:
            out[x] = (out[x][0], out[x][1] + 1)
        else:
            out[x] = (i, 1)
    return out
